'use strict';

// MODULES //

var tape = require( 'tape' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var Float64Array = require( '@stdlib/array/float64' );
var ndarray = require( '@stdlib/ndarray/base/ctor' );
var mode = require( './../lib' );


// FUNCTIONS //

/**
* Create 1D ndarray.
*
* @private
* @param {Float64Array} buffer - data buffer
* @param {NonNegativeInteger} length - length
* @param {integer} stride - stride
* @param {NonNegativeInteger} offset - index offset
* @returns {ndarray} ndarray
*/
function vector( buffer, length, stride, offset ) {
	return new ndarray( 'float64', buffer, [ length ], [ stride ], offset, 'row-major' );
}


// TESTS //

tape( 'main export is a function', function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof mode, 'function', 'main export is a function' );
	t.end();
});

tape( 'the function computes the mode', function test( t ) {
	var x = new Float64Array( [ 1.0, 2.0, 2.0, 3.0 ] );
	var v = mode( [ vector( x, 4, 1, 0 ) ] );
	t.strictEqual( v, 2.0, 'returns expected value' );

	x = new Float64Array( [ 5.0, 5.0, 2.0, 2.0 ] );
	v = mode( [ vector( x, 4, 1, 0 ) ] );
	t.strictEqual( v, 2.0, 'ties return smallest' );

	x = new Float64Array( [ NaN, 2.0 ] );
	v = mode( [ vector( x, 2, 1, 0 ) ] );
	t.strictEqual( isnan( v ), true, 'returns NaN' );

	t.end();
});

tape( 'if provided an empty vector, returns NaN', function test( t ) {
	var x = new Float64Array( [] );
	var v = mode( [ vector( x, 0, 1, 0 ) ] );
	t.strictEqual( isnan( v ), true, 'returns NaN' );
	t.end();
});
